def solid_rects(A, c, minside=3):
    res=[]
    H,W=A.shape
    for r1 in range(H):
        for r2 in range(r1+minside, H+1):
            row_ok = (A[r1:r2]==c).all(axis=0)
            # find runs
            i=0
            while i<W:
                if row_ok[i]:
                    j=i
                    while j<W and row_ok[j]: j+=1
                    if j-i>=minside and r2-r1>=minside: res.append((r1,r2,i,j))
                    i=j
                else: i+=1
    return res
